BEGIN TAXA;
TAXLABELS 'x1' x2 "x3";
END;
BEGIN CHARACTERS;
FORMAT DATATYPE=DNA NOLABELS;
MATRIX
ATGAAACCC
ATGAAACCT
ATGAAACCG
;
END;

#NEXUS
BEGIN DATA;
FORMAT DATATYPE=DNA INTERLEAVE;
MATRIX
[comment]
sp1 ATGAAA
sp2 ATGAAA

sp1 CCCGGG
sp2 CCCGGT
;
END;
